CREATE TABLE IF NOT EXISTS trades (id INTEGER PRIMARY KEY, symbol TEXT NOT NULL, side TEXT DEFAULT 'short', volume INTEGER, open INTEGER DEFAULT 0, gross_pl REAL, native_pl REAL, net_pl REAL, commission REAL, fees REAL, entry_price REAL, exit_price REAL, start_datetime TEXT, end_datetime TEXT, hold_minutes INTEGER, exec_count INTEGER, comment_count INTEGER, notes_excerpt TEXT, tags TEXT, shared INTEGER DEFAULT 0, is_clustered INTEGER DEFAULT 0, cluster_id TEXT, source_trade_ids TEXT, source_trade_count INTEGER DEFAULT 1, imported_at TEXT);
CREATE TABLE IF NOT EXISTS executions (execution_id INTEGER PRIMARY KEY, trade_id INTEGER NOT NULL REFERENCES trades(id), symbol TEXT, timestamp TEXT, quantity INTEGER, price REAL, side TEXT, broker_side TEXT, commission REAL, trans_fee REAL, ecn_fee REAL, sequence INTEGER, imported_at TEXT);
CREATE TABLE IF NOT EXISTS sync_log (id INTEGER PRIMARY KEY AUTOINCREMENT, synced_at TEXT NOT NULL, snapshot_id TEXT, trade_count INTEGER, new_trades INTEGER, updated_trades INTEGER, execution_count INTEGER, source_endpoint TEXT);
CREATE TABLE IF NOT EXISTS pre_trade_notes (id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, created_at TEXT NOT NULL, trade_id INTEGER REFERENCES trades(id), gemini_output TEXT, droppiness INTEGER, float_shares REAL, mkt_cap REAL, dt_overall_risk TEXT, dt_offering_ability TEXT, dt_overhead_supply TEXT, dt_historical TEXT, dt_cash_need TEXT, askedgar_risk TEXT, askedgar_dilution_pct REAL, cash_runway_months REAL, warrant_risk TEXT, short_bias TEXT, thesis TEXT, confidence INTEGER, invalidation TEXT, notes TEXT, company_name TEXT, sector TEXT, industry TEXT, exchange TEXT, ev REAL, os_shares REAL, net_cash_per_share REAL, inst_own_pct REAL, si_pct REAL, cash_burn_quarterly REAL, current_cash REAL, chart_image TEXT, dt_image TEXT, rsi_at_entry REAL, macd_status TEXT, timeframe TEXT, entry_price REAL, key_support REAL, key_resistance REAL, related_trade_ids TEXT, catalyst TEXT, setup_quality_score INTEGER);
CREATE TABLE IF NOT EXISTS trade_fundamentals (trade_id INTEGER PRIMARY KEY REFERENCES trades(id), symbol TEXT, droppiness INTEGER, float_shares REAL, mkt_cap REAL, dt_overall_risk TEXT, askedgar_risk TEXT, catalyst TEXT, linked_pre_trade_id INTEGER REFERENCES pre_trade_notes(id), updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_trades_symbol ON trades(symbol);
CREATE INDEX IF NOT EXISTS idx_trades_start_datetime ON trades(start_datetime);
CREATE INDEX IF NOT EXISTS idx_trades_net_pl ON trades(net_pl);
CREATE INDEX IF NOT EXISTS idx_executions_trade_id ON executions(trade_id);
CREATE INDEX IF NOT EXISTS idx_executions_timestamp ON executions(timestamp);
